from dataclasses import dataclass, field
from mashumaro import DataClassDictMixin
from mashumaro.helper import field_options
from mashumaro.config import BaseConfig
@dataclass
class Child(DataClassDictMixin):
 x: int = field(metadata=field_options(alias='xx'))
 class Config(BaseConfig):
  serialize_by_alias = True
@dataclass
class Parent(DataClassDictMixin):
 c: Child = field(metadata=field_options(flatten=True, flatten_rename={'x':'z'}))
p = Parent(Child(1)); print('renamed alias:', p.to_dict())
@dataclass
class A(DataClassDictMixin):
 x: int
@dataclass
class B(DataClassDictMixin):
 x: int
@dataclass
class Both(DataClassDictMixin):
 a: A = field(metadata=field_options(flatten=True, flatten_prefix=True))
 b: B = field(metadata=field_options(flatten=True, flatten_prefix=True))
print('two children:', Both.from_dict({'a_x': 1, 'b_x': 2}))
